   "lines": [
    "连携起手1：向前斩出一道剑气，造成 502% 武器攻击伤害。",
    "连携起手2：向前连续斩出 6 道剑气，每次造成 83% 武器攻击伤害。",
    "连携终结：向前斩出三道剑气波，对敌人造成 100% 武器攻击伤害。消耗所有连携点，每消耗 1 点就额外对敌人造成一次伤害。",
    "连携起手1：造成 502% 武器攻击伤害每 1 点连携点，该技能的连携起手技 +3% 技能范围",
    "连携起手2：造成 83% 武器攻击伤害总共造成 6 次伤害每 1 点连携点，该技能的连携起手技 +3% 技能范围该技能的连携起手技2额外 -40% 攻击速度",
    "该技能的连携起手技击中时，获得 1 层月晕",
    "连携终结：造成 100% 武器攻击伤害每消耗 1 点连携点，额外造成一次伤害，至多额外造成 4 次该技能的连携终结技额外 -40% 攻击速度每消耗 1 点连携点，该技能的连携终结技 +5% 技能范围",
    "该技能 +30% 连携终结技增幅该技能被触发时，额外 -25% 伤害",
    "该技能的连携起手技2额外 -40% 攻击速度该技能的连携终结技额外 -40% 攻击速度每 1 点连携点，该技能的连携起手技 +3% 技能范围每消耗 1 点连携点，该技能的连携终结技 +5% 技能范围该技能的连携起手技击中时，获得 1 层月晕该技能 +30% 连携终结技增幅该技能被触发时，额外 -25% 伤害"
   ],
